const unsigned long cq_link_smoke_count =
    sizeof cq_link_smoke_table / sizeof cq_link_smoke_table[0];

int main(void) {
    printf("cq_link_smoke: %lu generated cq_template_* symbols resolved at link\n",
           cq_link_smoke_count);
    /* Resolution is asserted by the LINK itself; this only reports it.
       The count is generated, so a YAML row that fails to reach the
       archive cannot silently shrink it — --check catches the drift. */
    return cq_link_smoke_count == 2880UL ? 0 : 1;
}
